namespace recovered_item_recalculate{
U charges(U s,U input,Ports&p){U index=input&255;if(static_cast<std::int32_t>(index)>=static_cast<std::int32_t>(p.read(s+0x248)))return 0;U e=p.read(s+0x250)+index*28;if(!e||p.word(e)!=10)return 0;U cost=p.word(e+6);if(cost<1||cost>18)return 0;static const unsigned char route[18]={0,1,2,3,4,5,8,6,6,6,6,6,8,7,7,7,7,7};U action=route[cost-1];if(action==8||!p.byte(e+12))return 0;if(action==0)return p.byte(s+0x28c);if(action==6)return p.byte(e+16);if(action==7)return 1;auto count=static_cast<std::int32_t>(p.read(s+0x258));if(count<=0)return 0;return static_cast<U>(count/static_cast<std::int32_t>(6-action));}
void recalculate(U s,U scratch,Ports&p){for(U i=0;i<8;++i)p.put_byte(scratch+i,0);U mask=0,index=0,offset=0,count=p.read(s+0x248);while(static_cast<std::int32_t>(index)<static_cast<std::int32_t>(count)){U e=static_cast<std::int32_t>(offset)>=0&&static_cast<std::int32_t>(index)<static_cast<std::int32_t>(p.read(s+0x248))?p.read(s+0x250)+offset:0;if(p.word(e)==10){U cost=p.word(e+6);if(cost>=1&&cost<=18){static const unsigned char route[18]={0,1,1,1,1,1,2,3,3,3,3,3,2,2,2,2,2,2};U action=route[cost-1];bool enabled=action==0?p.byte(e+12)!=0:action==1?static_cast<std::int32_t>(p.read(s+0x258))>0:action==3?p.byte(e+16)>0:true;if(enabled){if(action!=2&&static_cast<std::int32_t>(offset)<224)p.put_byte(scratch+index,charges(s,index,p));mask|=(1u<<(index&31))&255;}}}count=p.read(s+0x248);++index;offset+=28;}
 U changed=0;for(U i=0;i<8;++i)if(p.byte(scratch+i)!=p.byte(s+0x239+i))changed|=1u<<i;
 if(mask!=p.byte(s+0x238)||changed){p.put_byte(s+0x238,mask);for(U i=0;i<8;++i)p.put_byte(s+0x239+i,p.byte(scratch+i));U message=p.message();U player=p.player(p.read(s+0x268));if(player)p.notify(message,player,p.read(s+0x14),p.byte(s+0x238),changed,s+0x239);}
}}
